using Microsoft.EntityFrameworkCore; using SiapSD.Cognitive.Domain;
namespace SiapSD.Cognitive.Infrastructure;
public static class SeedData { public static async Task EnsureAsync(SiapSDDbContext db) { await db.Database.MigrateAsync(); if(await db.CognitiveDomains.AnyAsync()) return; var names=new[]{"Visual Reasoning","Fluid Reasoning","Visual Spatial","Working Memory","Auditory Memory","Attention","Processing Speed","Numerical Reasoning","Quantitative Reasoning","Verbal Reasoning","Sequencing","Executive Function","Planning / Problem Solving"}; var domains=names.Select((n,i)=>new CognitiveDomain{Code=$"D{i+1:00}",Name=n,DisplayOrder=i+1}).ToList(); db.CognitiveDomains.AddRange(domains); var specs=new[]{("Pattern Completion",0),("Odd One Out",0),("Classification",0),("Missing Part",0),("Rotation",2),("Matching Shape",2),("Spatial Position",2),("Shape Completion",2),("Visual Sequence Memory",3),("Spatial Memory",3),("Object Sequence",3),("Word Sequence",4),("Instruction Sequence",4),("Target Detection",5),("Visual Search",5),("Inhibitory Control",11),("Rule Switching",11),("Number Comparison",7),("Counting",7),("Number Sequence",7),("Visual Addition",8),("Story Problem",8),("Maze",12),("Grid Planning",12),("Shortest Path",12),("Symbol Matching",6)}; var subs=specs.Select((x,i)=>new Subtest{CognitiveDomainId=domains[x.Item2].Id,Code=$"S{i+1:00}",Name=x.Item1,DisplayOrder=i+1}).ToList(); db.Subtests.AddRange(subs); var bp=new AssessmentBlueprint{Code="STANDARD-5-6",Name="Standard Age 5-6 Cognitive Assessment",Description="Development assessment; not clinical IQ validity."}; db.AssessmentBlueprints.Add(bp); foreach(var s in subs.Where(x=>x.Name is "Pattern Completion" or "Missing Part" or "Odd One Out" or "Number Comparison" or "Visual Addition")) db.AssessmentBlueprintItems.Add(new AssessmentBlueprintItem{AssessmentBlueprintId=bp.Id,CognitiveDomainId=s.CognitiveDomainId,SubtestId=s.Id,InitialDifficulty=1,MinimumQuestions=1,MaximumQuestions=5,DisplayOrder=s.DisplayOrder}); var chosen=new[]{("Visual Reasoning","Pattern Completion",QuestionType.PatternChoice),("Visual Reasoning","Missing Part",QuestionType.MissingPart),("Visual Reasoning","Odd One Out",QuestionType.OddOneOut),("Numerical Reasoning","Number Comparison",QuestionType.MathChoice),("Quantitative Reasoning","Visual Addition",QuestionType.MathChoice)}; foreach(var (domain,sub,type) in chosen){var d=domains.Single(x=>x.Name==domain);var st=subs.Single(x=>x.Name==sub);for(var i=1;i<=5;i++){var q=new Question{Code=$"DEV-{d.Code}-{st.Code}-{i}",CognitiveDomainId=d.Id,SubtestId=st.Id,QuestionType=type,Difficulty=i,AgeMinMonths=48,AgeMaxMonths=84,Instruction="Choose best answer.",QuestionText=type==QuestionType.MathChoice?$"What is {i}+{i}?":$"Development {sub} item {i}: choose matching pattern.",StimulusJson="{\"developmentOnly\":true}",CorrectAnswerJson="\"B\"",IsPublished=true,IsAnswerRandomized=true};q.Options.AddRange(new[]{new QuestionOption{Code="A",Text="Option A",DisplayOrder=1},new QuestionOption{Code="B",Text=type==QuestionType.MathChoice?(i+i).ToString():"Correct pattern",DisplayOrder=2,IsCorrect=true},new QuestionOption{Code="C",Text="Option C",DisplayOrder=3}});db.Questions.Add(q);}} await db.SaveChangesAsync(); } }
